export function getNotificationForCategory(categoryId: string): Dhikr | null {
  const category = ADHKAR_CATEGORIES.find(c => c.id === categoryId);
  if (!category || category.adhkar.length === 0) return null;
  const randomIndex = Math.floor(Math.random() * category.adhkar.length);
  return category.adhkar[randomIndex];
}
